import PQueue from './source/index.js';

async function reproduce() {
  console.log('Test: Signal abort while task is queued should reject and remove from queue');

  const queue = new PQueue({ concurrency: 1 });

  // First task - takes some time, blocks the queue
  const blockerDone = new Promise<void>(resolve => {
    queue.add(async () => {
      console.log('Blocker task started');
      await new Promise(r => setTimeout(r, 2000));
      console.log('Blocker task done');
      resolve();
    });
  });

  // Wait a bit for the blocker to start
  await new Promise(r => setTimeout(r, 100));

  // Add a second task with an abort signal
  const controller = new AbortController();

  const taskPromise = queue.add(async () => {
    console.log('Second task started (should not happen if aborted while queued)');
    return 'done';
  }, { signal: controller.signal });

  // Verify task is in queue
  console.log('Queue size before abort:', queue.size);
  console.log('Pending before abort:', queue.pending);

  // Abort while task is still queued
  controller.abort();

  try {
    const result = await taskPromise;
    console.log('ERROR: Task resolved instead of rejected! Result:', result);
  } catch (error) {
    console.log('Task rejected as expected:', error);
  }

  // Wait for blocker to finish
  await blockerDone;

  // Check queue state after abort
  console.log('Queue size after abort:', queue.size);
  console.log('Pending after abort:', queue.pending);

  // If queue size is still 1, the task was NOT removed from the queue
  if (queue.size === 1) {
    console.log('BUG CONFIRMED: Task is still in the queue after abort!');
  } else {
    console.log('FIXED: Task was removed from the queue after abort');
  }
}

reproduce().catch(console.error);

