edits.newText:
return new Promise((resolve, reject) => {
	// Create a unique symbol for tracking this task
	const taskSymbol = Symbol(`task-${options.id}`);

	// Check if signal is already aborted before queuing
	if (options.signal?.aborted) {
		reject(options.signal.reason ?? new DOMException('This operation was aborted', 'AbortError'));
		return;
	}

	// Set up abort listener to remove from queue when aborted while queued
	let queuedAbortListener: (() => void) | undefined;
	if (options.signal) {
		queuedAbortListener = () => {
			// Remove from queue if still queued
			if (this.#queue.remove) {
				this.#queue.remove(options.id!);
			}

			// Reject with AbortError
			reject(options.signal!.reason ?? new DOMException('This operation was aborted', 'AbortError'));
		};
		options.signal.addEventListener('abort', queuedAbortListener, {once: true});
	}

	this.#queue.enqueue(async () => {
		// Remove the queued abort listener since task is now running
		if (queuedAbortListener) {
			options.signal?.removeEventListener('abort', queuedAbortListener);
			queuedAbortListener = undefined;
		}

		this.#pending++;

