import PQueue from './source/index.js';

async function reproduce() {
  console.log('Test: Signal abort while task is queued should REMOVE it from queue');

  const queue = new PQueue({ concurrency: 1 });
  let secondTaskStarted = false;

  // First task - takes some time, blocks the queue
  queue.add(async () => {
    console.log('Blocker task started');
    await new Promise(r => setTimeout(r, 2000));
    console.log('Blocker task done');
  });

  // Wait a bit for the blocker to start
  await new Promise(r => setTimeout(r, 100));

  // Add a second task with an abort signal
  const controller = new AbortController();

  const taskPromise = queue.add(async () => {
    secondTaskStarted = true;
    console.log('Second task started');
    return 'done';
  }, { signal: controller.signal });

  // Verify task is in queue
  console.log('Queue size before abort:', queue.size);  // Should be 1
  console.log('Pending before abort:', queue.pending);  // Should be 1 (blocker running)

  // Abort while task is still queued
  controller.abort();

  // Give a moment to process the abort
  await new Promise(r => setTimeout(r, 50));

  // Check queue state after abort
  console.log('Queue size after abort:', queue.size);
  console.log('Pending after abort:', queue.pending);

  // The BUG: Queue size should be 0 after abort, but it's still 1!
  const bugPresent = queue.size === 1;

  // Wait for task promise to settle
  try {
    const result = await taskPromise;
    console.log('ERROR: Task resolved instead of rejected!');
  } catch (error) {
    console.log('Task rejected (but still in queue)');
  }

  // Wait for blocker to finish
  await new Promise(r => setTimeout(r, 2500));

  // Final state
  console.log('Second task actually ran:', secondTaskStarted);

  if (bugPresent) {
    console.log('\n*** BUG CONFIRMED: Task was NOT removed from queue after abort ***');
    console.log('Expected: queue.size === 0 after abort');
    console.log('Actual: queue.size === 1 after abort (task still queued!)');
  } else {
    console.log('\n*** FIXED: Task was properly removed from queue ***');
  }
}

