import PQueue from './source/index.js';

async function reproduce() {
  console.log('Test: Signal abort while task is queued should REMOVE it from queue');

  const queue = new PQueue({ concurrency: 1 });
  let secondTaskStarted = false;

  // First task - takes some time, blocks the queue
  queue.add(async () => {
    console.log('Blocker task started');
    await new Promise(r => setTimeout(r, 2000));
    console.log('Blocker task done');
  });

  // Wait a bit for the blocker to start
  await new Promise(r => setTimeout(r, 100));

  // Add a second task with an abort signal
  const controller = new AbortController();

  const taskPromise = queue.add(async () => {
    secondTaskStarted = true;
    console.log('Second task started');
    return 'done';
  }, { signal: controller.signal }).catch(e => console.log('Caught:', e));

  // Verify task is in queue
  console.log('Queue size before abort:', queue.size);  // Should be 1
  console.log('Pending before abort:', queue.pending);  // Should be 1 (blocker running)

  // Abort while task is still queued
  controller.abort();

  // Give a moment to process the abort
  await new Promise(r => setTimeout(r, 100));

  // Check queue state after abort
  console.log('Queue size after abort:', queue.size);
  console.log('Pending after abort:', queue.pending);

  // The BUG: Queue size should be 0 after abort, but it's still 1!
  const bugPresent = queue.size === 1;

  // Wait for task promise to settle
  await taskPromise;

  // Wait for blocker to finish
  await new Promise(r => setTimeout(r, 2500));

  // Final state
  console.log('Second task actually ran:', secondTaskStarted);

  if (bugPresent) {
    console.log('\n*** BUG CONFIRMED: Task was NOT removed from queue after abort ***');
    console.log('Expected: queue.size === 0 after abort');
    console.log('Actual: queue.size === 1 after abort (task still queued!)');
  } else {
    console.log('\n*** FIXED: Task was properly removed from queue ***');
  }
}

reproduce().catch(console.error);

import { describe, test, expect } from "vitest";
import PQueue from "../source/index.js";

describe("p-queue regression", () => {
  test("basic queue", async () => {
    const queue = new PQueue({ concurrency: 2 });
    const results: number[] = [];
    await queue.add(() => { results.push(1); return Promise.resolve(); });
    await queue.add(() => { results.push(2); return Promise.resolve(); });
    await queue.onIdle();
    expect(results).toEqual([1,2]);
  });

  test("concurrency", async () => {
    const queue = new PQueue({ concurrency: 1 });
    let running = 0;
    let max = 0;
    const task = async () => { running++; max = Math.max(max, running); await new Promise(r=>setTimeout(r,10)); running--; };
    await Promise.all([queue.add(task), queue.add(task), queue.add(task)]);
    expect(max).toBe(1);
  });

  describe("abort signal while queued", () => {
    test("abort removes task from queue", async () => {
      const queue = new PQueue({ concurrency: 1 });

      // First task blocks the queue
      queue.add(async () => {
        await new Promise(r => setTimeout(r, 500));
      });

      // Wait for first task to start
      await new Promise(r => setTimeout(r, 50));

      // Add second task with abort signal
      const controller = new AbortController();
      let secondTaskRan = false;

      const taskPromise = queue.add(async () => {
        secondTaskRan = true;
        return 'done';
      }, { signal: controller.signal }).catch(() => {});

      // Verify task is in queue
      expect(queue.size).toBe(1);

      // Abort while task is queued
      controller.abort();

      // Wait for processing
      await new Promise(r => setTimeout(r, 50));

      // Task should be removed from queue
      expect(queue.size).toBe(0);

      await taskPromise;

      // Second task should not have run
      expect(secondTaskRan).toBe(false);
    });

    test("abort rejects with AbortError", async () => {
      const queue = new PQueue({ concurrency: 1 });

      // First task blocks the queue
      queue.add(async () => {
        await new Promise(r => setTimeout(r, 500));
      });

      await new Promise(r => setTimeout(r, 50));

      const controller = new AbortController();

      const taskPromise = queue.add(async () => 'done', { signal: controller.signal });

      // Abort
      controller.abort();

      await expect(taskPromise).rejects.toThrow('This operation was aborted');
    });

    test("already-aborted signal rejects immediately", async () => {
      const queue = new PQueue({ concurrency: 1 });

      const controller = new AbortController();
      controller.abort(); // Pre-abort

      const taskPromise = queue.add(async () => 'done', { signal: controller.signal });

      await expect(taskPromise).rejects.toThrow('This operation was aborted');

      // Task should never be in queue
      expect(queue.size).toBe(0);
    });

    test("abort with custom reason", async () => {
      const queue = new PQueue({ concurrency: 1 });

      queue.add(async () => {
        await new Promise(r => setTimeout(r, 500));
      });

      await new Promise(r => setTimeout(r, 50));

      const controller = new AbortController();
      const customError = new Error('Custom abort reason');

      const taskPromise = queue.add(async () => 'done', { signal: controller.signal });

      controller.abort(customError);

      await expect(taskPromise).rejects.toBe(customError);
    });

    test("abort does not affect already-running task", async () => {
      const queue = new PQueue({ concurrency: 1 });
      let taskRan = false;

      const controller = new AbortController();

      const taskPromise = queue.add(async () => {
        taskRan = true;
        await new Promise(r => setTimeout(r, 100));
        return 'done';
      }, { signal: controller.signal });

      // Wait for task to start
      await new Promise(r => setTimeout(r, 50));

      // Abort after task is running
      controller.abort();

      // Task should still complete
      const result = await taskPromise;
      expect(result).toBe('done');
      expect(taskRan).toBe(true);
    });

    test("multiple aborts don't cause issues", async () => {
      const queue = new PQueue({ concurrency: 1 });

      queue.add(async () => {
        await new Promise(r => setTimeout(r, 500));
      });

      await new Promise(r => setTimeout(r, 50));

      const controller = new AbortController();

      const taskPromise = queue.add(async () => 'done', { signal: controller.signal }).catch(() => {});

      // Abort multiple times
      controller.abort();
      controller.abort();
      controller.abort();

      await new Promise(r => setTimeout(r, 50));

      expect(queue.size).toBe(0);

      await taskPromise;
    });
  });
});

