        await new Promise(r => setTimeout(r, 500));
      });

      // Wait for first task to start
      await new Promise(r => setTimeout(r, 50));

      // Add second task with abort signal
      const controller = new AbortController();
      let secondTaskRan = false;

      const taskPromise = queue.add(async () => {
        secondTaskRan = true;
        return 'done';
      }, { signal: controller.signal }).catch(() => {});

      // Verify task is in queue
      expect(queue.size).toBe(1);

      // Abort while task is queued
      controller.abort();

      // Wait for processing
      await new Promise(r => setTimeout(r, 50));

      // Task should be removed from queue
      expect(queue.size).toBe(0);

      await taskPromise;

      // Second task should not have run
      expect(secondTaskRan).toBe(false);
    });

    test("abort rejects with AbortError", async () => {
      const queue = new PQueue({ concurrency: 1 });

      // First task blocks the queue
      queue.add(async () => {
        await new Promise(r => setTimeout(r, 500));
      });

      await new Promise(r => setTimeout(r, 50));

      const controller = new AbortController();

      const taskPromise = queue.add(async () => 'done', { signal: controller.signal });

      // Abort
      controller.abort();

      await expect(taskPromise).rejects.toThrow('This operation was aborted');
    });

    test("already-aborted signal rejects immediately", async () => {
      const queue = new PQueue({ concurrency: 1 });

      const controller = new AbortController();
      controller.abort(); // Pre-abort

      const taskPromise = queue.add(async () => 'done', { signal: controller.signal });

      await expect(taskPromise).rejects.toThrow('This operation was aborted');

      // Task should never be in queue
      expect(queue.size).toBe(0);
    });

    test("abort with custom reason", async () => {
      const queue = new PQueue({ concurrency: 1 });

      queue.add(async () => {
        await new Promise(r => setTimeout(r, 500));
      });

      await new Promise(r => setTimeout(r, 50));

      const controller = new AbortController();
      const customError = new Error('Custom abort reason');

      const taskPromise = queue.add(async () => 'done', { signal: controller.signal });

      controller.abort(customError);

      await expect(taskPromise).rejects.toBe(customError);
    });

    test("abort after task starts still rejects (expected behavior)", async () => {
      const queue = new PQueue({ concurrency: 1 });
      let taskRan = false;

      const controller = new AbortController();

      const taskPromise = queue.add(async () => {
        taskRan = true;
        await new Promise(r => setTimeout(r, 100));
        return 'done';
      }, { signal: controller.signal }).catch(() => {});

      // Wait for task to start
      await new Promise(r => setTimeout(r, 50));

      // Abort after task is running - this will still abort the task
      controller.abort();

      await taskPromise;

      // Task should have started but was aborted
      expect(taskRan).toBe(true);
    });

    test("multiple aborts don't cause issues", async () => {
      const queue = new PQueue({ concurrency: 1 });

      queue.add(async () => {
        await new Promise(r => setTimeout(r, 500));
      });

      await new Promise(r => setTimeout(r, 50));

      const controller = new AbortController();

      const taskPromise = queue.add(async () => 'done', { signal: controller.signal }).catch(() => {});

      // Abort multiple times
      controller.abort();
      controller.abort();
      controller.abort();

      await new Promise(r => setTimeout(r, 50));

      expect(queue.size).toBe(0);

      await taskPromise;
    });
  });
});

